import { test } from "node:test";
import assert from "node:assert/strict";
import { setTimeout as sleep, setImmediate as tick } from "node:timers/promises";
import { Batcher, type Reading } from "../src/telemetry/batcher.ts";
import { IngestServer } from "../src/telemetry/server.ts";
import { Lifecycle } from "../src/telemetry/lifecycle.ts";

function setup(opts: { lookupMs?: number; maxBatch?: number; drainTimeoutMs?: number } = {}) {
    const stored: Reading[] = [];
    const events: string[] = [];
    let closed = false;
    const sink = {
        async write(batch: Reading[]) {
            await tick();
            if (closed) throw new Error("sink is closed");
            stored.push(...batch);
            events.push(`write ${batch.length}`);
        },
        async close() {
            closed = true;
            events.push("close");
        },
    };
    const registry = {
        async lookup(token: string) {
            if (token === "hang") return new Promise<never>(() => {});
            await sleep(opts.lookupMs ?? 0);
            return token.startsWith("tok_") ? { deviceId: token.slice(4) } : null;
        },
    };
    const batcher = new Batcher(sink, opts.maxBatch ?? 100);
    const server = new IngestServer(registry, batcher);
    const lifecycle = new Lifecycle(server, batcher, sink, opts.drainTimeoutMs ?? 1000);
    const post = (token: string, n = 1) =>
        server.handle({ token, readings: Array.from({ length: n }, (_, i) => ({ metric: "temp_c", value: 20 + i, at: "2026-11-19T10:00:00Z" })) });
    return { stored, events, batcher, server, lifecycle, post };
}

test("readings are written in full batches as they arrive", async () => {
    const { post, stored, batcher } = setup({ maxBatch: 4 });
    for (let i = 0; i < 5; i++) assert.equal((await post("tok_th-1", 2)).status, 202);
    await tick();
    await tick();
    assert.equal(stored.length, 8);
    assert.equal(batcher.pending, 2);
});

test("shutting down an idle server flushes the buffer, then closes the sink", async () => {
    const { post, lifecycle, stored, events } = setup();
    await post("tok_th-1", 3);
    const report = await lifecycle.shutdown();
    assert.deepEqual(report, { inFlightAtStart: 0, drained: true });
    assert.equal(stored.length, 3);
    assert.deepEqual(events, ["write 3", "close"]);
});

test("requests that arrive after shutdown starts are turned away with 503", async () => {
    const { post, lifecycle } = setup();
    const stopping = lifecycle.shutdown();
    const res = await post("tok_th-1");
    assert.equal(res.status, 503);
    assert.equal(res.headers?.Connection, "close");
    await stopping;
});

test("a request in flight when SIGTERM arrives is acknowledged and stored", async () => {
    const { post, lifecycle, stored, events } = setup({ lookupMs: 20 });
    const inFlight = post("tok_th-7", 2);
    await tick();
    const report = await lifecycle.shutdown();
    assert.equal((await inFlight).status, 202);
    console.log("shutdown report:", report, "sink events:", events, "readings stored:", stored.length);
    assert.equal(stored.length, 2);
});

test("every reading acknowledged with 202 during a rolling restart is stored", async () => {
    const { post, lifecycle, stored, batcher } = setup({ lookupMs: 15, maxBatch: 50 });
    const requests = Array.from({ length: 10 }, (_, i) => post(`tok_dev-${i}`, 3));
    await tick();
    await lifecycle.shutdown();
    const acknowledged = (await Promise.all(requests)).filter((r) => r.status === 202).length * 3;
    assert.equal(acknowledged, 30);
    assert.equal(stored.length, acknowledged);
    assert.equal(batcher.pending, 0);
});

test("a stuck request doesn't block shutdown past the drain timeout", async () => {
    const { post, lifecycle, events } = setup({ drainTimeoutMs: 40 });
    void post("hang");
    await tick();
    const report = await lifecycle.shutdown();
    assert.deepEqual(report, { inFlightAtStart: 1, drained: false });
    assert.equal(events.at(-1), "close");
});

test("a second signal joins the shutdown already in progress", async () => {
    const { lifecycle, events } = setup();
    const [a, b] = await Promise.all([lifecycle.shutdown(), lifecycle.shutdown()]);
    assert.equal(a, b);
    assert.deepEqual(events, ["close"]);
});
